// pmor_bank.js -- "engine -> sound -> params" navigation for the lane devices (OP-1 style). One instance per patcher scope (lane perform view, lane editor).
// Controls are bound BY NAME to a PMOR schema id through the selection state (synth algo, drum pad, sampler slot); selecting something re-points every bound control
// (label, range, value from the cache) without sending anything. PMOR is the source of truth: values only ever flow IN through `param` (silent `set`); a control
// moves PMOR only by a user gesture (bc / br / bm -> outlet 0 `setparam`). Nothing here pushes defaults or stored values.
// Control varnames: bk_<name> plain dial (normalized 0..1, taper = log for time / frequency)   bkn_<name> live.dial normalized 0..1 (algo knobs: range depends on the algo)
//   bkr_<name> live.dial in schema units (range identical for every target)   bkm_<name> umenu / live.menu (index = value - lo)   bkt_<name> toggle / live.text (0/1)
//   bl_<name> label comment   bv_<name> readout comment ("2200 Hz", "-6.0 dB", "120 ms").   `sound` is the drum SOUND menu / dial (names refilled per drum group).
// Inlet messages: param <id> <v>            from PMOR (via [receive pmor_rx]): cache + silent redraw (no outlet)
//   bc <name> <n 0..1>  br <name> <v>  bm <name> <index>      user moved a control -> outlet 0 `setparam <id> <value>`
//   pick <kind> <n>   user selected algo|pad|slot (retarget; broadcast on outlet 2)
//   sel <kind> <n>    selection made elsewhere (broadcast from another instance): retarget, no broadcast, no setparam
//   page <n>          show the controls whose page is n (or -1 = always)       editor <0|1>   gated instances only draw while their window is open
//   schemabegin / schema <id> ... / schemaend (the `st` stream): controls whose id PMOR does not list are disabled, readout "n/a"
// Outlets: 0 setparam (-> guard -> send pmor_tx)   1 `slotpick <n>` (local pool browser)   2 `sel <kind> <n>` (-> send pmor_ui_sel)
// Argument `gated`: editor instance, caches until `editor 1`.
inlets = 1; outlets = 3;
var SOFT = 73;
